import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"離","description":"焦氏易林注 - 離","frontmatter":{"title":"離","description":"焦氏易林注 - 離"},"headers":[],"relativePath":"zh/classics/jiaoyilin/030.md","filePath":"zh/classics/jiaoyilin/030.md"}'),l={name:"zh/classics/jiaoyilin/030.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="離" tabindex="-1">離 <a class="header-anchor" href="#離" aria-label="Permalink to “離”">​</a></h1><h3 id="離-1" tabindex="-1">離 <a class="header-anchor" href="#離-1" aria-label="Permalink to “離”">​</a></h3><h3 id="離之乾" tabindex="-1">離之乾 <a class="header-anchor" href="#離之乾" aria-label="Permalink to “離之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>執轡四驪，王以為師。陰陽之明，載受東齊。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>遇卦離為東，互巽為齊。</p><h3 id="離之坤" tabindex="-1">離之坤 <a class="header-anchor" href="#離之坤" aria-label="Permalink to “離之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>春秋禱祝，解禍除憂，君子無咎。此與上皆兼用《離》象。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>離互兌為秋，兌口故禱祀。離伏震故曰春秋，坎故曰禍憂。伏艮為君子。○祝，依宋元本，汲古作祀。禍，依汲古，宋元本作過。</p><h3 id="離之屯" tabindex="-1">離之屯 <a class="header-anchor" href="#離之屯" aria-label="Permalink to “離之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>坐朝乘軒，據國子民。虞叔受命，六合和親。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為朝、為軒車，艮為坐，震為乘，故曰坐朝乘軒。艮為據、為國，震為子，坤為民，故據國子民。艮為叔，震為歡。虞伏巽為命，故曰虞叔受命。坎為和、為合，數六，故曰六合。○坐朝，宋元本作坐車，依汲古。六合和親，宋本、汲古作和合六親，茲依元本。</p><h3 id="離之蒙" tabindex="-1">離之蒙 <a class="header-anchor" href="#離之蒙" aria-label="Permalink to “離之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>開戶下堂，與福相迎。祿於公室，曾祖以昌。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為門戶，艮為堂，震為門，坤為下，故曰開戶下堂。震為福祿，正反震，故曰與福相迎。震為公，坎為室，艮為祖。</p><h3 id="離之需" tabindex="-1">離之需 <a class="header-anchor" href="#離之需" aria-label="Permalink to “離之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>高木腐巢，漏濕難居。不去甘棠，使我無憂。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為木，離為巢，在上故曰高木，坎水故曰腐巢，故曰漏濕。下二句言巢雖漏濕，只不伐甘棠即無傾覆之憂也。</p><h3 id="離之訟" tabindex="-1">離之訟 <a class="header-anchor" href="#離之訟" aria-label="Permalink to “離之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>三女為姦，俱游高園。背室夜行，與伯笑言。不忍主母，為失醴酒，冤尤誰告。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坤為女，震數三，故曰三女。坎為姦，巽為高，坤為園，故俱游高園。艮為背，坎為室、為夜，艮覆故曰背室夜行。震為伯、為笑言、為主，坤為母，故曰主母。坎為酒、為冤尤。《列女傳》：&quot;周大夫主父妻淫於鄰人，恐主父覺，置毒酒使婢進之，婢知之，佯僵覆酒，受笞&quot;。○忍，汲古訛認。末二句各本皆作&quot;為設歡酒，冤尤誰禱&quot;，依汲古《履》之《既濟》校。告，音垢，林意謂女行不端，婢不忍從主母毒主父，佯失酒，反遭笞也。</p><h3 id="離之師" tabindex="-1">離之師 <a class="header-anchor" href="#離之師" aria-label="Permalink to “離之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>漏巵盛酒，無以養老。春貸黍稷，年歲實有。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>履道坦坦，平安無咎。坎為酒，震為巵，伏巽，故曰漏巵。坤為老，坤喪，故不能養老。震為黍稷、為春，坤為年歲。震為履、為大塗，故曰履道坦坦。○無，宋元本作何，依汲古。</p><h3 id="離之比" tabindex="-1">離之比 <a class="header-anchor" href="#離之比" aria-label="Permalink to “離之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>松柏枝葉，常茂不落。君子惟體，日富安樂。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為木、為堅，故曰松柏、曰不落。艮為君子、為安，坤為身，故曰體。○惟體，汲古作歡寧，安作求，均依宋元本。</p><h3 id="離之小畜" tabindex="-1">離之小畜 <a class="header-anchor" href="#離之小畜" aria-label="Permalink to “離之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>夫婦不諧，為燕攻齊。良弓不張，騎劫憂亡。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>互《離》。下震上巽，震夫巽婦，而正反兩兌口相對故曰不諧。兌為燕，巽為齊，坎為弓，坎伏，故曰不張。騎劫，燕將，代樂毅戰死，故曰亡。○第四句宋元本作騎駟憂凶，茲依汲古。</p><h3 id="離之履" tabindex="-1">離之履 <a class="header-anchor" href="#離之履" aria-label="Permalink to “離之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>出令不勝，反為大災。強不克弱，君受其憂。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>巽為令、兌為反巽、為毀折，故曰不勝，曰反為大災，卦以一陰為主，故強不克弱，言五陽不能勝此一陽也。乾為君。君受其憂者，言上乾恐被陰消也。</p><h3 id="離之泰" tabindex="-1">離之泰 <a class="header-anchor" href="#離之泰" aria-label="Permalink to “離之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>犇牛相錯，敗亂緒業，民不得作。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為牛，震為奔，坤為敗亂，伏巽為緒，坤為民，坤僵故不作。○犇牛，汲古作奔走，緒業作諸緒，依宋元本。</p><h3 id="離之否" tabindex="-1">離之否 <a class="header-anchor" href="#離之否" aria-label="Permalink to “離之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>載璧秉圭，請命於河。周公克敏，沖人瘳愈。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為玉，坤為車，故曰載璧。艮為手，故曰秉圭。巽為命，乾為河，伏震為周、為公、為沖人，艮堅故曰瘳。沖人者，成王，言成王有疾，周公以圭璧禱於河，使王疾愈也。事見《史記魯世家》。</p><h3 id="離之同人" tabindex="-1">離之同人 <a class="header-anchor" href="#離之同人" aria-label="Permalink to “離之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>素車偽馬，不任重負。王侯出征，憂危為咎。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為車、為白，故曰素車。震為馬，坤虛故曰偽馬，蓋芻靈之屬。坤柔故不任重負。震為王、為諸侯、為出征，坎為憂危。○偽，汲古作為，依宋元本。</p><h3 id="離之大有" tabindex="-1">離之大有 <a class="header-anchor" href="#離之大有" aria-label="Permalink to “離之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>大樹之子，同條共母。比至火中，枝葉盛茂。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮坎皆為木，坤為母，本卦離為火。《左傳昭三年》：&quot;火中，寒暑乃退。&quot;註：心星，以季夏昏中而暑退。季夏之時，草木長成，故曰枝葉盛茂。○同，汲古作百，至作之，均依宋元本。</p><h3 id="離之謙" tabindex="-1">離之謙 <a class="header-anchor" href="#離之謙" aria-label="Permalink to “離之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>壅遏堤防，水不得行。火盛陽光，陰霓伏藏，走歸其鄉。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《大畜》。○末句宋元本作走婦其歸，依汲古。</p><h3 id="離之豫" tabindex="-1">離之豫 <a class="header-anchor" href="#離之豫" aria-label="Permalink to “離之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>五嶽四瀆，潤洽為德。行不失理，民賴恩福。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>○潤洽，依《頤》之《大畜》校，宋元本作合潤，汲古作含潤。</p><h3 id="離之隨" tabindex="-1">離之隨 <a class="header-anchor" href="#離之隨" aria-label="Permalink to “離之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>駕駿南游，虎驚我牛。陰不奉陽，其光顯揚。言之謙謙，奉義解患。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為南，艮為虎、為牛，震為驚，上下卦陰皆居上，故曰陰不奉陽，即不承陽也。艮為光，初至四正反震，故曰言之謙謙。震為解也。○牛，宋元本作羊，雖合兌象，然與游不協，依汲古。艮牛象，雖見於《易》，久失傳，《易林》屢見，汲古不誤。</p><h3 id="離之蠱" tabindex="-1">離之蠱 <a class="header-anchor" href="#離之蠱" aria-label="Permalink to “離之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>早霜晚雪，傷害禾麥。損功棄力，飢無所食。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為禾麥，兌毀故曰傷害，巽隕落，故損功棄力。兌為食，震為虛，故曰飢無所食。震虛象。《歸妹上六》&quot;承虛筐也&quot;即以震為虛。</p><h3 id="離之臨" tabindex="-1">離之臨 <a class="header-anchor" href="#離之臨" aria-label="Permalink to “離之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>岐周海隅，有樂無憂。可以避難，全身保財。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為周，坤為海、為憂，震樂故無憂。坤為財。○有，汲古作獨，依宋元本。按：《孟子》：&quot;伯夷避紂，居北海之濱，太公避紂，居東海之濱，聞西伯善養老而歸於周&quot;，林似述其事。</p><h3 id="離之觀" tabindex="-1">離之觀 <a class="header-anchor" href="#離之觀" aria-label="Permalink to “離之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>陰蔽其陽，日暗不明。君憂其國，求騂得黃。駒犢從行。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>卦陰盛陽衰，故曰陰蔽其陽。艮為日，坤黑故不明。坤為國、為憂，伏震為君，坤為馬，故曰騂黃。騂，赤色，黃，黃色馬也。乾為赤，坤為黃，乾伏，故不得騂而得黃。艮為求、為少，故曰駒，坤牛故曰犢，坤母故駒犢從行。○日，宋本、汲古皆作目，惟元本作日，艮為日亦失傳象也。</p><h3 id="離之噬嗑" tabindex="-1">離之噬嗑 <a class="header-anchor" href="#離之噬嗑" aria-label="Permalink to “離之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>金城鐵郭，上下同力。政平民歡，寇不敢賊。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為城郭、為金鐵，正反震，故曰上下同力。坎為平、為民、為寇賊。○鐵，元本作佳，依宋本、汲古。</p><h3 id="離之賁" tabindex="-1">離之賁 <a class="header-anchor" href="#離之賁" aria-label="Permalink to “離之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>平公有疾，迎醫秦國。和不能愈，晉人赴告。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為平、為疾，震為公，艮為國，伏兌，故曰秦國。坎為和，震為晉。按：《左傳成十年》：&quot;晉景公有疾，秦伯使醫緩為之，醫言病入膏盲［當作肓］，不能為，公果卒&quot;。赴告者，言赴告列國公喪也。○愈，宋元本作知，汲古作治，皆非，依《需》之《巽》校。赴告，宋元本作赴國，汲古作疑惑，皆不合，依《坎》之《萃》校。告，音谷，與國協。</p><h3 id="離之剝" tabindex="-1">離之剝 <a class="header-anchor" href="#離之剝" aria-label="Permalink to “離之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>戴堯扶禹，松喬彭祖。西遇王母，道路夷易，無敢難者。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>乾為王，一陽在上，群陰戴之，故曰戴堯扶禹。艮為壽，故曰松喬彭祖。赤鬆子、王子喬、彭籛，皆仙人而享大年者。伏兌為西，坤為母，伏乾，故曰王母。坤為道路。○戴作載，非，依宋元本。松，宋元本作從，依汲古。</p><h3 id="離之復" tabindex="-1">離之復 <a class="header-anchor" href="#離之復" aria-label="Permalink to “離之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>羔羊皮革，君子朝服。輔政扶德，以合萬國。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《離》。</p><h3 id="離之無妄" tabindex="-1">離之無妄 <a class="header-anchor" href="#離之無妄" aria-label="Permalink to “離之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>振鐘鼓樂，將軍受福。安帖之家，虎狼為憂。履危不殆，師行何咎。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為鍾、為樂。鼓樂，言奏樂也。震為武人，故曰將軍。艮為安、為家、為虎狼，震為履，伏坤為師。○振、樂，宋元本作據鐘鼓翼，為作與，殆作強，均依汲古。</p><h3 id="離之大畜" tabindex="-1">離之大畜 <a class="header-anchor" href="#離之大畜" aria-label="Permalink to “離之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>嫡庶不明，孽亂生殃，陳失其邦。震為長子，嫡也，乃三至上正反震，故曰嫡庶不明。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為陳，四至上震覆，故陳失其邦。艮為邦。</p><h3 id="離之頤" tabindex="-1">離之頤 <a class="header-anchor" href="#離之頤" aria-label="Permalink to “離之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>鳥驚狐鳴，國亂不寧。上弱下強，為陰所刑。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為鳥、為驚、為鳴，艮為狐，坤為國、為亂，艮孤陽在上，故曰上弱。震為健，故曰下強。坤為刑，中四爻重坤，故曰為陰所刑。○狐鳴，宋本、汲古作孤鴻，茲依元本。</p><h3 id="離之大過" tabindex="-1">離之大過 <a class="header-anchor" href="#離之大過" aria-label="Permalink to “離之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>被繡夜行，不見文章。安坐於堂，乃無咎殃。長子帥師，得其正常。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>卦通《頤》。坤為夜，震為行，坤為繡、為文章，坤黑故不見。艮為坐、為堂，震為長子。坤為師。三四句言艮止義，五六句言震動義也。○於，宋元本作玉，茲依汲古。宋本作《坎》林。</p><h3 id="離之坎" tabindex="-1">離之坎 <a class="header-anchor" href="#離之坎" aria-label="Permalink to “離之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>六月採芑，征伐無道。張仲方叔，克勝飲酒。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>六月採芑，《小雅》篇名，頌周宣王也。張仲、方叔，皆宣王臣，《詩》：&quot;張仲孝友，方叔召虎&quot;是也。坎為月，數六，故曰六月。互震為芑，艮手為採，震為征伐。坎為仲，艮為叔，坎為酒。○克，元本作克，從宋本、汲古，宋本作《大過》林。</p><h3 id="離之離" tabindex="-1">離之離 <a class="header-anchor" href="#離之離" aria-label="Permalink to “離之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>時乘六龍，為帝使東。達命宣旨，無所不通。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。互艮為時，震為龍，坎數六，故曰六龍。震為帝、為東，本卦巽為命，風散故達命宣旨，無所不通。</p><h3 id="離之咸" tabindex="-1">離之咸 <a class="header-anchor" href="#離之咸" aria-label="Permalink to “離之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>昧暮乘車，東至伯家。逾梁越河，濟脫無他。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>伏《損》。坤為黑、為夜，故曰昧暮。震為車、為乘、為東、為伯，艮為家，故東至伯家。艮為梁，坤為河，震往，故曰逾越、曰濟脫。</p><h3 id="離之恒" tabindex="-1">離之恒 <a class="header-anchor" href="#離之恒" aria-label="Permalink to “離之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>東風解凍，和氣兆升，年歲豐登。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震東巽風，乾為寒、為凍，震為解，故曰東風解凍。巽為氣，兌悅，故曰和氣。坤為年歲。○末句元本作年豐歲登，依宋本、汲古。</p><h3 id="離之遯" tabindex="-1">離之遯 <a class="header-anchor" href="#離之遯" aria-label="Permalink to “離之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>三狸捕鼠，遮遏前後。死於圜城，不得脫走。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>古貓未為家畜，故以狸捕鼠，狸，狐屬。艮為狸，數三，故曰三狸。艮為鼠，艮止，故曰遮遏前後。伏坤為死，乾為圜，艮為城，艮止故難脫。○死於圜城，宋本作無於圜城，元本作無於遠域，茲依汲古。圜城者，獄城也，《周禮司圜》：鄭司農雲：&quot;圜，土獄城也&quot;。</p><h3 id="離之大壯" tabindex="-1">離之大壯 <a class="header-anchor" href="#離之大壯" aria-label="Permalink to “離之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>綏德孔明，履祿久長。貴且有光，疾病憂傷。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為履，乾為祿、為久長、為貴、為光，伏坤為疾病憂傷。</p><h3 id="離之晉" tabindex="-1">離之晉 <a class="header-anchor" href="#離之晉" aria-label="Permalink to “離之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>三虎搏狼，力不相當。如摧腐枯，一擊破亡。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，數三，故曰三虎。艮為狼、為手，故搏狼。離中虛，故曰枯腐。艮為擊，坎為破，坤為亡。○腐枯，宋元本作壅祜，茲依汲古。</p><h3 id="離之明夷" tabindex="-1">離之明夷 <a class="header-anchor" href="#離之明夷" aria-label="Permalink to “離之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>使伯採桑，狠不肯行。與叔爭訟，更相毀傷。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為桑，坎為狠，坎陷故不肯行。坎上下兌口相背，故曰爭訟。坎破故曰毀傷。○採桑，宋元本作東乘，狠作恨，茲依汲古。</p><h3 id="離之家人" tabindex="-1">離之家人 <a class="header-anchor" href="#離之家人" aria-label="Permalink to “離之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>抱空握虛，鴞驚我雛，利去不來。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦象。離中爻伏艮，故曰抱、曰握。離為空虛。艮為鴞，震子故曰雛。震為驚，巽為利，風散故不來。○抱，元本作把，依宋本、汲古。</p><h3 id="離之睽" tabindex="-1">離之睽 <a class="header-anchor" href="#離之睽" aria-label="Permalink to “離之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>李華再實，鴻卵降集。仁哲以興，蔭國受福。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《離》。第四句宋元本作隆國無賊，汲古作不賊，茲依《比》之《訟》等林校改。</p><h3 id="離之蹇" tabindex="-1">離之蹇 <a class="header-anchor" href="#離之蹇" aria-label="Permalink to “離之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>東山皋洛，勇悍不服。金玦玩好，衣為身賊。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>《左傳閔二年》：&quot;晉侯使太子申生伐東山皋洛氏，佩之金玦，後太子果敗&quot;。離東艮山，離為赤，東山皋洛，赤狄別種，故用以為象。艮為金，伏兌為玦。坎為賊。○洛，依宋元本，汲古作落，雖與今《左傳》同，然《易林》用經往往字與今經異，疑宋本是、汲古非也。第二句元本作一朝隕落，宋元悍作捍，茲依汲古。又汲古多絲麻不作句，宋元本均無，依之。</p><h3 id="離之解" tabindex="-1">離之解 <a class="header-anchor" href="#離之解" aria-label="Permalink to “離之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>飛蚊污身，為邪所牽。青蠅分白，貞孝放逐。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蚊，震為飛，坎水故曰污。震為青，伏巽為蠅、為白。○蚊，宋元本作文，依汲古。牽，汲古作率，貞作真，均依宋元本。青蠅，《詩》篇名，傷讒而作。貞孝放逐，言伯奇、申生為後母所讒而被放也。</p><h3 id="離之損" tabindex="-1">離之損 <a class="header-anchor" href="#離之損" aria-label="Permalink to “離之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>南山黃竹，三身六目。出入制命，東里宣政。主尊君安，鄭國無患。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為南、為竹，艮山，數三，坤身，故曰三身六目。未詳。伏巽為命令，坤為里，震東故曰東里，指子產也。震為主，坤為安、為居，坤為國、為鄭。《說文》：&quot;鄭，地町町然平也&quot;，象坤形。○黃竹，各本皆作大木。三身六目，宋元本作文身其目，汲古作丈身六目。第三四五句，宋元本作&quot;制命出命，東里田畝。尊主安居&quot;，汲古作&quot;制命出文，東里宣敷。尊主安居&quot;，茲依《蠱》之《旅》校改，韻皆協矣。按：此皆指子產治鄭事。</p><h3 id="離之益" tabindex="-1">離之益 <a class="header-anchor" href="#離之益" aria-label="Permalink to “離之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>泉起昆侖，東出玉門。流為九河，無有憂患。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮山坤水故曰泉起昆侖。艮為門，震為東、為玉，故東出玉門。坤為河，震數九，故曰九河。坤為憂患，震解故無。言河出昆侖山，過玉門關，播為九河也。</p><h3 id="離之夬" tabindex="-1">離之夬 <a class="header-anchor" href="#離之夬" aria-label="Permalink to “離之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>命短不長，中年夭傷。思及哭堂，哀其子亡。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>巽為命、為長，巽覆兌折，故曰命短不長。乾為年，兌少，伏坤為死，故曰中年夭傷。坤為思，伏艮為堂，兌口為哭。震為子，伏艮，震覆故子亡。○思及，宋元本作鬼泣，依汲古。</p><h3 id="離之姤" tabindex="-1">離之姤 <a class="header-anchor" href="#離之姤" aria-label="Permalink to “離之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>君臣不和，上下失宜，宗子哀歌。通《復》。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>坤為臣，震為君，臣上君下故曰不和、曰失宜。震為宗、為子、為歌，坤憂故曰哀歌。○末句宋本作宗子哭歌，元本作宋子哭歌，依汲古。</p><h3 id="離之萃" tabindex="-1">離之萃 <a class="header-anchor" href="#離之萃" aria-label="Permalink to “離之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>苛政日作，螟食華葉。割下啖上，民被其賊。秋無所得。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為政，艮為日。巽為螟，兌為食、為華，故曰暝食華葉。坤為下，艮為刀，故曰割下，兌口在上故曰啖上。坤為民，互巽為賊，故曰被其民賊。兌為秋，巽隕落故無得。</p><h3 id="離之升" tabindex="-1">離之升 <a class="header-anchor" href="#離之升" aria-label="Permalink to “離之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>南行載鎧，登履九魁。車傷牛罷，日暮嗟咨。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為南，伏艮為鎧。《說文》：&quot;鎧，甲也&quot;。坤為車、為牛、為暮，伏艮為日，坤憂震語故嗟咨。第二句義未詳。○載，宋元本作戴，從汲古。履，宋元作場，從汲古。罷，音疲。魁當為疑。</p><h3 id="離之困" tabindex="-1">離之困 <a class="header-anchor" href="#離之困" aria-label="Permalink to “離之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>春東夏南，隨陽有功，與利相逢。伏《賁》。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>互震為春、為東，離為夏、為南，故曰春東夏南。離為陽，震為隨，本卦巽為利。</p><h3 id="離之井" tabindex="-1">離之井 <a class="header-anchor" href="#離之井" aria-label="Permalink to “離之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>頭尾顛倒，不知緒處，君失其國。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏《噬嗑》。艮為首、為尾，初至四正反艮，故曰顛倒。巽為緒，震為君，艮為國，互坎故曰失國。</p><h3 id="離之革" tabindex="-1">離之革 <a class="header-anchor" href="#離之革" aria-label="Permalink to “離之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>言無要約，不成契券。殷叔季姬，公孫爭之。強入委禽，不悅於心。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《革》。○於心，各本皆作子南，依《頤》之《革》校。禽，汲古訛命。</p><h3 id="離之鼎" tabindex="-1">離之鼎 <a class="header-anchor" href="#離之鼎" aria-label="Permalink to “離之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>缺破不成，胎卵不生，不見其形。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>互兌為缺破，震為胎、為卵，震伏巽隕故不生。○破，汲古作陷，茲依宋元本。</p><h3 id="離之震" tabindex="-1">離之震 <a class="header-anchor" href="#離之震" aria-label="Permalink to “離之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>見蛇交司，惜蚖畏惡，心乃無悔。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蛇、為蚖，互坎為心。義未詳。○悟，汲古作卧，蚖作蜓，依宋元本。</p><h3 id="離之艮" tabindex="-1">離之艮 <a class="header-anchor" href="#離之艮" aria-label="Permalink to “離之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>河水孔穴，壞敗我室。水深無涯，魚鱉傾倒。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>坎為河水，震為孔，艮為穴，故曰河水孔穴。艮為室、為鱉，伏巽為魚。○倒，元本作側，依宋本、汲古。</p><h3 id="離之漸" tabindex="-1">離之漸 <a class="header-anchor" href="#離之漸" aria-label="Permalink to “離之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>五獄四瀆，地得以安。高而不危，敬慎避患。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮山，坎數五，故曰五獄。坎為瀆，巽數四，故曰四瀆。巽為高，艮安，故不危。坎為患，巽順故曰敬慎。○敬慎，汲古作驚懼，茲依宋元本。</p><h3 id="離之歸妹" tabindex="-1">離之歸妹 <a class="header-anchor" href="#離之歸妹" aria-label="Permalink to “離之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>南至之日，陽消不息。北風冽寒，萬物藏伏。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>離日震南，故曰南至之日，上下卦陰在陽上故曰陽消不息。坎為北、為寒，伏巽，故曰北風。震為萬物，坎為藏伏。○冽，宋元本作烈，藏伏作伏藏，茲依汲古，然伏仍不協，疑為匿字。</p><h3 id="離之豐" tabindex="-1">離之豐 <a class="header-anchor" href="#離之豐" aria-label="Permalink to “離之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>五利四福，俱田高邑。黍稷盛茂，多獲高稻。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>巽為利，卦數五故曰五利。震為福，卦數四，故曰四福。艮為邑，巽為高，震為耕，故曰俱田高邑。震為黍稷、為盛茂、為稻。○田，宋元本作佃，高作居，稻作積，均依汲古。</p><h3 id="離之旅" tabindex="-1">離之旅 <a class="header-anchor" href="#離之旅" aria-label="Permalink to “離之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>公孫駕車，載游東齊。延陵說產，遺季紵衣。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《益》，各本下多疾病悲哀四字，與上文不類，斷為衍文，依《乾》之《益》校刪。</p><h3 id="離之巽" tabindex="-1">離之巽 <a class="header-anchor" href="#離之巽" aria-label="Permalink to “離之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>蛟虯當道，民困愁苦。望羊置群，長子在門。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇，故曰蛟虯，伏震為道，故曰蛟虯當道。坎為民、為愁苦，坎陷，故曰民困愁苦。互兌為羊，艮為門，震為長子。</p><h3 id="離之兌" tabindex="-1">離之兌 <a class="header-anchor" href="#離之兌" aria-label="Permalink to “離之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>金玉滿堂，忠直乘危。三老凍餓，鬼奪其室。求魚河海，網舉必得。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮為金、為堂，震為玉，故曰金玉滿堂。坎為忠直、為危、為凍，震數三，艮壽，故曰三老。三老，鄉官也。坎為鬼、為河海，艮為求，互巽為魚，離為網。○堂，宋元本作室，非，茲依汲古。其，汲古作我，茲依宋元本。按：林詞義吉凶不協，疑中二句為衍文。</p><h3 id="離之渙" tabindex="-1">離之渙 <a class="header-anchor" href="#離之渙" aria-label="Permalink to “離之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>日入明匿，陽晶隱伏。小人勞心，求事不得。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>離伏，故曰日入明匿。晶精通。坎為隱伏、為心、為勞，震為人，艮為小，故曰小人勞心。艮為求，風散故不得。○明匿，宋元本作幽慝，晶作明，均依汲古。</p><h3 id="離之節" tabindex="-1">離之節 <a class="header-anchor" href="#離之節" aria-label="Permalink to “離之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>頻逢社飲，失利後福。不如子息，舊居故處。申請必得，乃無大悔。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為社，兌口為飲。古社日最重春秋兩社，皆祭後鄉飲，故曰頻逢社飲。巽為利，巽伏故失利。震為後、為福，故曰後福。震為子息、為申請，艮為居處。○社，依宋元本，汲古作招，非。必得，宋元本作必與，依汲古。</p><h3 id="離之中孚" tabindex="-1">離之中孚 <a class="header-anchor" href="#離之中孚" aria-label="Permalink to “離之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>南有嘉魚，駕黃取。魴鱮詡詡，利來無憂。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為南，巽為魚，震福故曰嘉魚。震為黃，黃馬也。正反巽故曰、曰魴鱮。巽為利。○，汲古、宋本皆作游，茲依元本，嘉魚，《小雅》詩篇名。</p><h3 id="離之小過" tabindex="-1">離之小過 <a class="header-anchor" href="#離之小過" aria-label="Permalink to “離之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>黃裳建元，文德在身。祿佑洋溢，封為齊君。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為衣、為黃，《坤六五》：&quot;黃裳元吉&quot;，故曰建元。艮為身，坤為文，卦上下皆坤爻，故曰文德在身。震為福佑、為君，巽為齊。○宋元本下多&quot;賈市無門，股肱多根&quot;二句，根當為恨，豈有上文如是之吉、下忽凶乎，其為衍文無疑，故從汲古不錄。</p><h3 id="離之既濟" tabindex="-1">離之既濟 <a class="header-anchor" href="#離之既濟" aria-label="Permalink to “離之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>口不從心，欲東反西。與意乖戾，動舉失便。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>離東坎西。○舉，元本作步，依宋本、汲古。便，依汲古，宋元本皆作使。</p><h3 id="離之未濟" tabindex="-1">離之未濟 <a class="header-anchor" href="#離之未濟" aria-label="Permalink to “離之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>虎狼之鄉，日爭凶訟。叨爾為長，不能定從。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>卦有三艮形，故曰虎狼之鄉。離正覆兌相背，故曰爭訟。不能定從，言不能定從約。虎狼之鄉，謂秦也。○從，汲古訛證，依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
